#include "dp.h"
#include <stdlib.h>
#include <string.h>
int dp_knapsack(const int*w,const int*v,size_t n,int cap,long long*out){if(!w||!v||!out||cap<0)return 0;long long*d=calloc((size_t)cap+1,sizeof(*d));if(!d)return 0;for(size_t i=0;i<n;i++){if(w[i]<=0||v[i]<0){free(d);return 0;}for(int c=cap;c>=w[i];c--){long long z=d[c-w[i]]+v[i];if(z>d[c])d[c]=z;}}*out=d[cap];free(d);return 1;}
int dp_chain(const int*d,size_t n,long long*out){if(!d||!n||!out)return 0;long long*t=calloc(n*n,sizeof(*t));if(!t)return 0;for(size_t l=2;l<=n;l++)for(size_t i=0;i+l<=n;i++){size_t j=i+l-1;t[i*n+j]=LLONG_MAX;for(size_t k=i;k<j;k++){long long z=t[i*n+k]+t[(k+1)*n+j]+(long long)d[i]*d[k+1]*d[j+1];if(z<t[i*n+j])t[i*n+j]=z;}}*out=t[n-1];free(t);return 1;}
int dp_lcs(const char*a,const char*b,size_t*out){if(!a||!b||!out)return 0;size_t m=strlen(a),n=strlen(b);size_t*d=calloc((m+1)*(n+1),sizeof(*d));if(!d)return 0;for(size_t i=1;i<=m;i++)for(size_t j=1;j<=n;j++)d[i*(n+1)+j]=a[i-1]==b[j-1]?d[(i-1)*(n+1)+j-1]+1:(d[(i-1)*(n+1)+j]>d[i*(n+1)+j-1]?d[(i-1)*(n+1)+j]:d[i*(n+1)+j-1]);*out=d[m*(n+1)+n];free(d);return 1;}
int dp_obst(const int*f,size_t n,long long*out){if(!f||!out)return 0;long long*d=calloc(n*n,sizeof(*d)),*s=calloc(n*n,sizeof(*s));if(!d||!s){free(d);free(s);return 0;}for(size_t i=0;i<n;i++)d[i*n+i]=s[i*n+i]=f[i];for(size_t l=2;l<=n;l++)for(size_t i=0;i+l<=n;i++){size_t j=i+l-1;s[i*n+j]=s[i*n+j-1]+f[j];long long b=LLONG_MAX;for(size_t r=i;r<=j;r++){long long z=(r>i?d[i*n+r-1]:0)+(r<j?d[(r+1)*n+j]:0);if(z<b)b=z;}d[i*n+j]=s[i*n+j]+b;}*out=n?d[n-1]:0;free(d);free(s);return 1;}
int dp_bellman(const int*e,size_t ec,size_t n,size_t src,long long*d){if(!e||!d||!n||src>=n)return 0;for(size_t i=0;i<n;i++)d[i]=LLONG_MAX;d[src]=0;for(size_t p=1;p<n;p++){int ch=0;for(size_t k=0;k<ec;k++){int u=e[3*k],v=e[3*k+1],w=e[3*k+2];if(u<0||v<0||(size_t)u>=n||(size_t)v>=n)return 0;if(d[u]!=LLONG_MAX&&d[u]+w<d[v])d[v]=d[u]+w,ch=1;}if(!ch)break;}for(size_t k=0;k<ec;k++){int u=e[3*k],v=e[3*k+1],w=e[3*k+2];if(d[u]!=LLONG_MAX&&d[u]+w<d[v])return -1;}return 1;}
int dp_floyd(long long*a,size_t n){if(!a)return 0;for(size_t k=0;k<n;k++)for(size_t i=0;i<n;i++)for(size_t j=0;j<n;j++)if(a[i*n+k]!=LLONG_MAX&&a[k*n+j]!=LLONG_MAX&&a[i*n+k]+a[k*n+j]<a[i*n+j])a[i*n+j]=a[i*n+k]+a[k*n+j];for(size_t i=0;i<n;i++)if(a[i*n+i]<0)return -1;return 1;}
int dp_tsp(const int*g,size_t n,long long*out){if(!g||!out||n<2||n>16)return 0;size_t S=(size_t)1<<n;long long*d=malloc(S*n*sizeof(*d));if(!d)return 0;for(size_t i=0;i<S*n;i++)d[i]=LLONG_MAX;d[n]=0;for(size_t m=1;m<S;m++)if(m&1)for(size_t u=0;u<n;u++)if((m>>u&1)&&d[m*n+u]!=LLONG_MAX)for(size_t v=1;v<n;v++)if(!(m>>v&1)&&g[u*n+v]>0){size_t q=m|(1u<<v);long long z=d[m*n+u]+g[u*n+v];if(z<d[q*n+v])d[q*n+v]=z;}long long b=LLONG_MAX;for(size_t u=1;u<n;u++)if(d[(S-1)*n+u]!=LLONG_MAX&&g[u*n]>0&&d[(S-1)*n+u]+g[u*n]<b)b=d[(S-1)*n+u]+g[u*n];free(d);if(b==LLONG_MAX)return 0;*out=b;return 1;}
